import{_ as i,a0 as p,w as a,s as n,I as s,x as e,a1 as o,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"機器人學影響 CIO 角色的 3 種方式 | LCTT x X-CMD","titleTemplate":false,"description":"機器人學影響 CIO 角色的 3 種方式 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"機器人學影響 CIO 角色的 3 種方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"機器人學影響 CIO 角色的 3 種方式 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20171103 3 ways robotics affects the CIO role","title":"機器人學影響 CIO 角色的 3 種方式","tag":"201806","desc":""},"relativePath":"201806/20171103 3 ways robotics affects the CIO role.md","filePath":"[post].md"}'),f={name:"201806/20171103 3 ways robotics affects the CIO role.md"};function C(u,t,m,I,O,T){const r=p("Link");return a(),n("div",null,[t[19]||(t[19]=s("h1",{id:"機器人學影響-cio-角色的-3-種方式",tabindex:"-1"},[e("機器人學影響 CIO 角色的 3 種方式 "),s("a",{class:"header-anchor",href:"#機器人學影響-cio-角色的-3-種方式","aria-label":"Permalink to “機器人學影響 CIO 角色的 3 種方式”"},"​")],-1)),t[20]||(t[20]=s("blockquote",null,[s("p",null,"機器人流程自動化如何影響 CIO ？考慮這些可能。")],-1)),t[21]||(t[21]=s("p",null,[s("img",{src:"https://enterprisersproject.com/sites/default/files/styles/620x350/public/cio_ai.png?itok=toMIgELj",alt:"配圖"})],-1)),t[22]||(t[22]=s("p",null,"隨着 2017 的結束，許多 CIO 們的 2018 年目標也將確定。或許你們將參與到機器人流程自動化（RPA）中。多年以來，RPA 對許多公司來説只是一個可望不可及的概念。但是隨着組織被迫變得越來越敏捷高效，RPA 所具有的潛在優勢開始受到重視。",-1)),s("p",null,[t[1]||(t[1]=e("根據 Redwood Sofeware 和 Sapio Research 的最新 ",-1)),o(r,{href:"https://www.redwood.com/press-releases/it-decision-makers-speak-59-of-business-processes-could-be-automated-by-2022/"},{default:l(()=>[...t[0]||(t[0]=[e("研究報告",-1)])]),_:1}),t[2]||(t[2]=e("，IT 決策者們相信，未來 5 年有 59% 的業務可以被自動化處理，從而產生新的速度和效率，並且消減相應的重複性的人工工作量的崗位。但是，目前在相應崗位上沒有實施 RPA 的公司中，有 20% 的公司員工超過 1000 人。",-1))]),t[23]||(t[23]=s("p",null,"對於 CIO 們來説，RPA 會潛在影響你在業務中的角色和你的團隊。隨着 RPA 的地位在 2018 年中越來越重要，CIO 們和其它 IT 決策者的角色也能會受到如下三種方式的改變：",-1)),t[24]||(t[24]=s("h3",{id:"成為戰略性變革代理人的機會增加",tabindex:"-1"},[e("成為戰略性變革代理人的機會增加 "),s("a",{class:"header-anchor",href:"#成為戰略性變革代理人的機會增加","aria-label":"Permalink to “成為戰略性變革代理人的機會增加”"},"​")],-1)),t[25]||(t[25]=s("p",null,"隨着壓力的增長，用最少的時間做更多的事，內部流程越來越重要。在每個企業中，員工們每天做着既重要又枯燥的一些任務。這些任務可能是枯燥且重複性的任務，但是要求他們必須快速完成且不能出錯。",-1)),s("p",null,[s("strong",null,[t[4]||(t[4]=e("[有關你的自動化策略的 ROI 建議，查看我們相關的文章，",-1)),o(r,{href:"https://enterprisersproject.com/article/2017/11/how-improve-roi-automation-4-tips?sc_cid=70160000000h0aXAAQ"},{default:l(()=>[...t[3]||(t[3]=[e("如何在自動化方面提升 ROI：4 個小提示",-1)])]),_:1}),t[5]||(t[5]=e("。]",-1))])]),t[26]||(t[26]=d('<p>在財務中從後台的一些操作到採購、供應鏈、賬務、客户服務、以及人力資源，在一個組織中幾乎所有的崗位都有一些枯燥的任務。這就為 CIO 們提供了一個機會，將 IT 與業務聯合起來，成為使用 RPA 進行戰略變革的先鋒。</p><p>除了過去的屏幕抓取技術，機器人現在已經實現可定製化，即插即用的解決方案可以根據企業的需要進行設計。使用這種以流程為中心的方法，企業不僅可以將以前由人來完成的任務進行自動化，也可以將應用程序和系統特定任務自動化，比如 ERP 和企業其它應用程序。</p><p>為端到端的流程實施更高級別的自動化將是 CIO 們的價值所在。CIO 們將會站在這種機遇的最前沿。</p><h3 id="重新關注人和培訓" tabindex="-1">重新關注人和培訓 <a class="header-anchor" href="#重新關注人和培訓" aria-label="Permalink to “重新關注人和培訓”">​</a></h3><p>技術的變動將讓員工更加恐慌，尤其是當這些自動化的變動涉及到他們每日職責的相當大的部分。CIO 們應該清楚地告訴他們，RPA 將如何讓他們的角色和責任變得更好，以及用數據説明的、最終將影響到他們底線的戰略決策。</p><p>當實施 RPA 時，清晰明確地表達出“人對組織的成功來説是很重要的”信息是很關鍵的，並且，這種成功需要使技術和人的技能實現適當的平衡。</p><p>CIO 們也應該分析工作流並實施更好的流程，這種流程能夠超越以前由終端用户完成的特定任務。通過端到端的流程自動化，CIO 們可以讓員工表現更加出色。</p><p>因為在整個自動化的過程中，提升和培訓員工技術是很重要的，CIO 們必須與企業高管們一起去決定，幫助員工自信地應對變化的培訓項目。</p><h3 id="需要長遠的規劃" tabindex="-1">需要長遠的規劃 <a class="header-anchor" href="#需要長遠的規劃" aria-label="Permalink to “需要長遠的規劃”">​</a></h3><p>為確保機器人流程自動化的成功，甲方必須有一個長期的方法。這將要求一個彈性的解決方案，它將對整個業務模型有好處，包括消費者。比如，當年亞馬遜為他的 Prime 消費者推廣快速投遞服務時，他們不僅在他們的倉庫中重新調整了訂單交付流程，他們也自動化了他們的在線客户體驗，讓它們變得更簡化、更快速，並且讓消費者比以前更容易下訂單。</p><p>在即將到來的一年裏，CIO 們可以用同樣的方法來應用技術，構建整體的解決方案來改變組織的動作方式。裁員只會讓最終效益產生很大影響，但是流程自動化將使 CIO 們能夠通過優化和授權來考慮更大的問題。這種方法讓 CIO 們去為他們自己和 RPA 構建長期的信譽。這反過來將強化 CIO 們作為探路者的角色，併為整個組織的成功作出貢獻。</p><p>對於 CIO 們來説，採用一個長期的、策略性的方法讓 RPA 成功，需要時間和艱苦的努力。儘管如此，那些致力於創建一種人力和技術平衡戰略的 CIO 們，將會在現在和將來實現更大的價值。</p><hr>',13)),s("p",null,[t[7]||(t[7]=e("via: ",-1)),o(r,{href:"https://enterprisersproject.com/article/2017/11/3-ways-robotics-affects-cio-role"},{default:l(()=>[...t[6]||(t[6]=[e("https://enterprisersproject.com/article/2017/11/3-ways-robotics-affects-cio-role",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=e("作者：",-1)),o(r,{href:"https://enterprisersproject.com/user/dennis-walsh"},{default:l(()=>[...t[8]||(t[8]=[e("Dennis Walsh",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),o(r,{href:"https://github.com/qhwdw"},{default:l(()=>[...t[9]||(t[9]=[e("qhwdw",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:l(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),o(r,{href:"https://linux.cn/"},{default:l(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const x=i(f,[["render",C]]);export{P as __pageData,x as default};
